#nullable enable // autogenerated

using System;
using System.Collections.Generic;
using MVZ2Logic.Resources;

namespace MVZ2.Resources
{
    public class SpriteLookupKey : IEquatable<SpriteLookupKey>
    {
        public SpriteReference reference;
        public HashSet<string> tags = new HashSet<string>();

        public SpriteLookupKey(SpriteReference reference, params string[] tags)
        {
            this.reference = reference;
            foreach (var tag in tags)
            {
                this.tags.Add(tag);
            }
        }
        public override bool Equals(object obj)
        {
            if (obj is SpriteLookupKey other)
            {
                return Equals(other);
            }
            return base.Equals(obj);
        }
        public override int GetHashCode()
        {
            var hash = reference.GetHashCode(); 
            foreach (var item in tags)
            {
                if (item != null)
                {
                    // 使用异或运算，确保顺序无关性
                    // 注意：如果集合中有重复元素（针对List），异或可能会导致抵消，
                    // 但对于 HashSet 来说是安全的。
                    hash ^= item.GetHashCode();
                }
            }
            return hash;
        }
        public override string ToString()
        {
            return $"{reference}({string.Join(',', tags)})";
        }
        public bool Equals(SpriteLookupKey other)
        {
            return reference == other.reference && tags.SetEquals(other.tags);
        }
    }
}
